package com.fireplatform;

import com.fasterxml.jackson.databind.*;
import com.fireplatform.shared.*;
import com.fireplatform.siminventory.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.junit.jupiter.api.Test;
import static com.fireplatform.siminventory.SimInventoryInputs.Operation;
import static org.assertj.core.api.Assertions.*;

class SimInventoryInputsTest {
    final ObjectMapper json=new ObjectMapper().setPropertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE).enable(DeserializationFeature.USE_BIG_INTEGER_FOR_INTS).enable(DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS);
    final SimInventoryInputs inputs=new SimInventoryInputs(json);
    Map<String,Object> body(Operation operation){var m=new LinkedHashMap<String,Object>();m.put("expected_inventory_revision",0L);m.put("reason",operation==Operation.CORRECT?"Correction evidence":"");if(operation==Operation.ISSUE)m.put("issued_to","Ordinary recipient note");return m;}
    SimInventoryInputs.Command parse(Map<String,Object> body,Operation operation)throws Exception{return inputs.command(json.writeValueAsBytes(body),operation);}
    void bad(org.assertj.core.api.ThrowableAssert.ThrowingCallable work){assertThatThrownBy(work).isInstanceOfSatisfying(ApiError.class,e->{assertThat(e.status).isEqualTo(400);assertThat(e.code).isEqualTo("INVALID_REQUEST");assertThat(e.getMessage()).doesNotContain("SECRET");});}
    @Test void everyOperationHasExactlyThreeOrFourRequiredNonNullKeys()throws Exception{for(Operation operation:Operation.values()){assertThat(body(operation)).hasSize(operation==Operation.ISSUE?3:2);assertThat(parse(body(operation),operation).expectedInventoryRevision()).isZero();for(String key:body(operation).keySet()){var missing=body(operation);missing.remove(key);bad(()->parse(missing,operation));var nil=body(operation);nil.put(key,null);bad(()->parse(nil,operation));}}}
    @Test void crossDomainReadOnlyAndNonIssueRecipientFieldsAreUnknown(){for(Operation operation:Operation.values())for(String key:List.of("card_id","tenant_id","status","revision","recorded_at","changed","operation","device_id")){var m=body(operation);m.put(key,"SECRET");bad(()->parse(m,operation));}var m=body(Operation.RECEIVE);m.put("issued_to","not allowed");bad(()->parse(m,Operation.RECEIVE));}
    @Test void scalarTypesAreNeverCoerced(){for(Operation operation:Operation.values())for(String key:body(operation).keySet())for(Object value:List.of(true,List.of("x"),Map.of("x",1))){var m=body(operation);m.put(key,value);bad(()->parse(m,operation));}var m=body(Operation.ISSUE);m.put("issued_to",1);bad(()->parse(m,Operation.ISSUE));}
    @Test void rawRevisionsRejectNegativeZeroExponentFractionStringAndUnsafe()throws Exception{String valid=json.writeValueAsString(body(Operation.RECEIVE));for(String raw:List.of("-0","-1","0.0","0e0","\"0\"","9007199254740992","9223372036854775808"))bad(()->inputs.command(valid.replace("\"expected_inventory_revision\":0","\"expected_inventory_revision\":"+raw).getBytes(StandardCharsets.UTF_8),Operation.RECEIVE));}
    @Test void safeMaximumAndZeroRemainExact()throws Exception{assertThat(parse(body(Operation.RECEIVE),Operation.RECEIVE).expectedInventoryRevision()).isZero();var m=body(Operation.RECEIVE);m.put("expected_inventory_revision",SimInventoryInputs.MAX_SAFE);assertThat(parse(m,Operation.RECEIVE).expectedInventoryRevision()).isEqualTo(SimInventoryInputs.MAX_SAFE);}
    @Test void duplicateTrailingMalformedAndNonObjectJsonFail()throws Exception{String valid=json.writeValueAsString(body(Operation.RECEIVE));for(String raw:List.of("null","[]","{}",valid+" {}",valid.substring(0,valid.length()-1)+",\"reason\":\"SECRET\"}",valid.replace("\"reason\":\"\"","\"reason\":\"bad\\q\"")))bad(()->inputs.command(raw.getBytes(StandardCharsets.UTF_8),Operation.RECEIVE));}
    @Test void issuedToIsPlainTextNormalizedWithJavaTrimNotDirectoryIdentity()throws Exception{var m=body(Operation.ISSUE);m.put("issued_to"," \r\nCrew / 000Recipient\tDesk <literal> \t ");assertThat(parse(m,Operation.ISSUE).issuedTo()).isEqualTo("Crew / 000Recipient\tDesk <literal>");assertThat(SimInventoryInputs.issuedTo("\u00a0\u3000")).isEqualTo("\u00a0\u3000");}
    @Test void issuedToRejectsEmptyControlBadUtf16AndOverLimit(){for(String value:Arrays.asList(null,""," \r\n\t ","a\u0000b","\u000b","\u007f","\u0085","\ud800","x".repeat(1001)))bad(()->SimInventoryInputs.issuedTo(value));assertThat(SimInventoryInputs.issuedTo("😀".repeat(500))).hasSize(1000);}
    @Test void reasonRetainsAllValidOriginalWhitespaceAndDoesNotUseRecipientTrimming(){for(String reason:List.of(""," "," \r\n\ta\t\r\n ","<literal>"))assertThat(SimInventoryInputs.reason(reason)).isEqualTo(reason);for(String reason:Arrays.asList(null,"a\u0000b","\u000b","\u007f","\u0085","\ud800"))bad(()->SimInventoryInputs.reason(reason));}
    @Test void correctionNeedsNonblankJavaTrimEvidenceButPreservesOriginalText()throws Exception{var m=body(Operation.CORRECT);for(String reason:List.of(""," "," \r\n\t ")){m.put("reason",reason);bad(()->parse(m,Operation.CORRECT));}m.put("reason"," \tCorrected with evidence\n ");assertThat(parse(m,Operation.CORRECT).reason()).isEqualTo(" \tCorrected with evidence\n ");m.put("reason","\u00a0");assertThat(parse(m,Operation.CORRECT).reason()).isEqualTo("\u00a0");}
    @Test void reasonUsesCentralUtf16TechnicalLimit(){assertThat(SimInventoryInputs.reason("😀".repeat(500))).hasSize(Limits.MAX_CHANGE_REASON_LENGTH);bad(()->SimInventoryInputs.reason("😀".repeat(501)));}
    @Test void transitionMatrixAllowsDirectManualRegistrationAndOnlyExplicitScrapCorrection(){for(String from:List.of("UNREGISTERED","AVAILABLE","ISSUED"))for(Operation operation:Operation.values())assertThat(SimInventoryInputs.allows(operation,from)).isEqualTo(operation!=Operation.CORRECT);for(Operation operation:Operation.values())assertThat(SimInventoryInputs.allows(operation,"SCRAPPED")).isEqualTo(operation==Operation.SCRAP||operation==Operation.CORRECT);assertThat(SimInventoryInputs.allows(null,"AVAILABLE")).isFalse();assertThat(SimInventoryInputs.allows(Operation.RECEIVE,null)).isFalse();assertThat(SimInventoryInputs.allows(Operation.RECEIVE,"UNKNOWN")).isFalse();}
    @Test void operationTargetsAndNamespacesAreExactClosedContracts(){assertThat(Arrays.stream(Operation.values()).map(Operation::namespace)).containsExactly("sim-inventory-receive","sim-inventory-issue","sim-inventory-recover","sim-inventory-scrap","sim-inventory-correct");assertThat(Operation.RECEIVE.target()).isEqualTo("AVAILABLE");assertThat(Operation.RECOVER.target()).isEqualTo("AVAILABLE");assertThat(Operation.CORRECT.target()).isEqualTo("AVAILABLE");assertThat(Operation.ISSUE.target()).isEqualTo("ISSUED");assertThat(Operation.SCRAP.target()).isEqualTo("SCRAPPED");}
    @Test void collectionFilterIsOnlyRegisteredStatusNotVirtualOrCaseCoercion(){assertThat(SimInventoryInputs.status(null)).isNull();for(String status:SimInventoryInputs.REGISTERED)assertThat(SimInventoryInputs.status(status)).isEqualTo(status);for(String status:List.of("UNREGISTERED","available"," AVAILABLE ",""))bad(()->SimInventoryInputs.status(status));}
    @Test void actorConfirmationPasswordFieldIsRejected()throws Exception{var m=body(Operation.RECEIVE);m.put("actor_password","Synthetic-Confirmation-Password");bad(()->parse(m,Operation.RECEIVE));}
    @Test void pagingIsCanonicalAndBoundedBySharedPolicy(){assertThat(SimInventoryInputs.page(null,1)).isEqualTo(1);assertThat(SimInventoryInputs.page("1000000",1)).isEqualTo(1000000);for(String raw:List.of("-0","01","1.0","1e0","2147483648",""))bad(()->SimInventoryInputs.page(raw,1));}
    @Test void canonicalFingerprintHasFixedRecipientSlotAndNeverPassword()throws Exception{String card="123e4567-e89b-12d3-a456-426614174000";for(Operation operation:Operation.values()){var command=parse(body(operation),operation);assertThat(SimInventoryCommands.fingerprint("tenant-a",card,operation,command)).isEqualTo(List.of("tenant-a",operation.namespace(),card,0L,operation==Operation.ISSUE?"Ordinary recipient note":"",operation==Operation.CORRECT?"Correction evidence":""));assertThat(json.writeValueAsString(SimInventoryCommands.fingerprint("tenant-a",card,operation,command))).doesNotContain("recorded_at");}}
}
